package com.bookreads.api

import com.bookreads.dto.LeaderboardEntryDto
import com.bookreads.dto.SessionDto
import com.bookreads.dto.SessionSyncRequest
import com.bookreads.dto.UserDto
import io.ktor.client.HttpClient
import io.ktor.client.call.body
import io.ktor.client.request.get
import io.ktor.client.request.post
import io.ktor.client.request.setBody
import io.ktor.http.ContentType
import io.ktor.http.HttpStatusCode
import io.ktor.http.contentType
import kotlinx.serialization.Serializable

interface BookApi {
    suspend fun registerUser(username: String): UserDto
    suspend fun getUser(username: String): UserDto?
    suspend fun syncSession(request: SessionSyncRequest): SessionDto
    suspend fun getSession(clientId: String): SessionDto?
    suspend fun getLeaderboard(window: String): List<LeaderboardEntryDto>
}

@Serializable
private data class RegisterUserBody(val username: String)

class KtorBookApi(
    private val httpClient: HttpClient,
    private val baseUrl: String,
) : BookApi {

    override suspend fun registerUser(username: String): UserDto =
        httpClient.post("$baseUrl/users") {
            contentType(ContentType.Application.Json)
            setBody(RegisterUserBody(username))
        }.body()

    override suspend fun getUser(username: String): UserDto? {
        val response = httpClient.get("$baseUrl/users/$username")
        return if (response.status == HttpStatusCode.NotFound) null else response.body()
    }

    override suspend fun syncSession(request: SessionSyncRequest): SessionDto =
        httpClient.post("$baseUrl/sessions/sync") {
            contentType(ContentType.Application.Json)
            setBody(request)
        }.body()

    override suspend fun getSession(clientId: String): SessionDto? {
        val response = httpClient.get("$baseUrl/sessions/$clientId")
        return if (response.status == HttpStatusCode.NotFound) null else response.body()
    }

    override suspend fun getLeaderboard(window: String): List<LeaderboardEntryDto> =
        httpClient.get("$baseUrl/leaderboard") {
            url { parameters.append("window", window) }
        }.body()
}

package com.bookreads.sync

import com.bookreads.api.BookApi
import com.bookreads.dto.SessionSyncRequest
import com.bookreads.session.LocalSessionStore
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch

class SessionSyncService(
    private val api: BookApi,
    private val sessionStore: LocalSessionStore,
) {
    private var periodicJob: Job? = null

    suspend fun syncOnce(username: String, endedAt: String? = null) {
        try {
            val session = sessionStore.getActiveSession().let { flow ->
                var result: com.bookreads.storage.ActiveSession? = null
                val job = kotlinx.coroutines.GlobalScope.launch {
                    flow.collect {
                        result = it
                        throw kotlinx.coroutines.CancellationException()
                    }
                }
                job.join()
                result
            } ?: return
            api.syncSession(
                SessionSyncRequest(
                    clientId = session.clientId,
                    username = username,
                    bookTitle = session.bookTitle,
                    startedAt = session.startedAt,
                    endedAt = endedAt,
                    durationSec = session.elapsedSec,
                )
            )
        } catch (_: Exception) {
        }
    }

    fun startPeriodicSync(username: String, scope: CoroutineScope) {
        periodicJob?.cancel()
        periodicJob = scope.launch {
            while (isActive) {
                delay(30_000L)
                syncOnce(username)
            }
        }
    }

    fun stopSync() {
        periodicJob?.cancel()
        periodicJob = null
    }
}

