package com.bookreads.session

import com.bookreads.storage.ActiveSession
import com.bookreads.storage.AppPreferences
import com.bookreads.storage.LocalStorageService
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.flow.map
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.runBlocking
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull

class FakeLocalStorageService : LocalStorageService {
    private val prefs = MutableStateFlow(AppPreferences())

    override fun getUsername(): Flow<String?> = prefs.map { it.username }
    override suspend fun setUsername(username: String?) { prefs.update { it.copy(username = username) } }
    override fun getActiveSession(): Flow<ActiveSession?> = prefs.map { it.activeSession }
    override suspend fun saveActiveSession(session: ActiveSession) { prefs.update { it.copy(activeSession = session) } }
    override suspend fun clearActiveSession() { prefs.update { it.copy(activeSession = null) } }
}

class LocalSessionStoreTest {

    private val storage = FakeLocalStorageService()
    private val store = LocalSessionStore(storage)

    @Test
    fun `save session then read it back`() = runBlocking {
        val session = ActiveSession(
            clientId = "client-1",
            bookTitle = "Kotlin in Action",
            startedAt = "2026-02-22T10:00:00Z",
            elapsedSec = 120L,
        )

        store.saveActiveSession(session)

        assertEquals(session, store.getActiveSession().first())
    }

    @Test
    fun `clear session returns null`() = runBlocking {
        val session = ActiveSession(
            clientId = "client-2",
            bookTitle = "Clean Code",
            startedAt = "2026-02-22T11:00:00Z",
            elapsedSec = 60L,
        )

        store.saveActiveSession(session)
        store.clearActiveSession()

        assertNull(store.getActiveSession().first())
    }
}
